filter: drop-shadow(8px 8px 10px gray);
}
#img2 {
filter: drop-shadow(10px 10px 7px lightblue);
}

---

#img1 {
filter: grayscale(1);
}
#img2 {
filter: 
  grayscale(60%);
}
#img3 {
filter: grayscale(0.4);
}

---

#img1 {
filter: hue-rotate(200deg);
}
#img2 {
filter: 
  hue-rotate(90deg);
}
#img3 {
filter: hue-rotate(-90deg);
}

---

#img1 {
filter: invert(0.3);
}
#img2 {
filter: 
  invert(70%);
}
#img3 {
filter: invert(100%);
}

---

#img1 {
filter: opacity(80%);
}
#img2 {
filter: 
  opacity(50%);
}
#img3 {
filter: opacity(0.2);
}

---

#img1 {
filter: saturate(0);
}
#img2 {
filter: 
  saturate(100%);
}
#img3 {
filter: saturate(200%);
}

---

#img1 {
filter: sepia(1);
}
#img2 {
filter: sepia(60%);
}
#img3 {
filter: sepia(0.4);
}
```

